blocosAtivos: 
    .space 63
blocosEndereco:
    .align 2
    .space 252
.align 2
backupCenario:
    .space 32768
.text
main:
    
    j desenharTelaInicial
desenharTelaInicial:
	lui $8, 0x1001
	lw $4, 0($8)
	sw $4, 0($8)
	addi $9, $0, 8192
forTelaInicial:
	beq $9, $0, esperarOpcao
	addi $8, $8, 4
	addi $9, $9, -1
	lw $4, 0($8)
	sw $4, 0($8)
	j forTelaInicial
esperarOpcao:

    lui $14, 0xFFFF
    lw $17, 0($14)
    andi $17, $17, 1
    beq $17, $0, esperarOpcao
    lw $17, 4($14)
    li $15, 27
    beq $17, $15, sairJogo
    li $15, 32
    bne $17, $15, esperarOpcao
    lui $8, 0x1001
    addi $8, $8, 512
    lui $9, 0x1001
    addi $11, $0, 64
    j desenharCenario

sairJogo:
    addi $2, $0, 10
    syscall
    
	
# $8  = endereço do pixel atual
# $9  = quantidade de pixels restantes
# $4  = cor temporária do pixel
forCenario:
    beq $9, $0, fimForCenario

    lw $4, 0($10)
    sw $4, 0($8)
    sw $4, 98304($8)

    addi $8, $8, 4
    addi $10, $10, 4
    addi $9, $9, -1
    j forCenario

fimForCenario:
    jr $31



# $8  = posição do jogador
# $9  = contador de pixels
# $16 = posição atual da bola
# $18 = posição inicial do jogador
# $19 = posição inicial da bola
# $20 = direção da bola

desenharCenario:
    # Posição inicial da bola
    lui $16, 0x1001
    addi $16, $16, 26876

    lui $8, 0x1001
    addi $9, $0, 8192
    la $10, Cenario
    jal forCenario

    # Posição do jogador
    lui $8, 0x1001
    addi $8, $8, 30440

    # Posição inicial do jogador
    addi $18, $8, 0

    # Posição inicial da bola
    addi $19, $16, 0

    # Velocidade horizontal da bola
    addi $20, $0, 0

    # Direção vertical da bola
    addi $21, $0, 0
    
    #Quantas vezes o jogador clicou espaço
    addi $22, $0, 0
    la $24, blocosAtivos
    li $25, 63
    li $26, 1

inicializarBlocos:
    beq $25, $0, fimInicializarBlocos
    sb $26, 0($24)
    addi $24, $24, 1
    addi $25, $25, -1
    j inicializarBlocos

fimInicializarBlocos:
    jal desenharQuadrados
    j controlarPlayer


# $8  = endereço atual do jogador
# $14 = endereço do dispositivo de teclado
# $15 = limite temporário ou código de tecla
# $17 = estado do teclado ou tecla pressionada
# $18 = posição inicial do jogador

controlarPlayer:
    jal nulltime

    lui $14, 0xFFFF

    lw $17, 0($14)
    andi $17, $17, 1

    beq $17, $0, desenharPlayer

    lw $17, 4($14)
	
	
    addi $15, $0, 27
    beq $17, $15, endGame
    
    addi $15, $0, 32
    beq $17, $15, startGame

    addi $15, $0, 'a'
    beq $17, $15, digA

    addi $15, $0, 'd'
    beq $17, $15, digD

    j desenharPlayer


digA:
    addi $15, $18, -152
    ble $8, $15, desenharPlayer

    addi $8, $8, -8
    j desenharPlayer


digD:
    addi $15, $18, 160
    bge $8, $15, desenharPlayer

    addi $8, $8, 8
    j desenharPlayer


# $8  = endereço atual de desenho
# $4  = cor temporária
# $9  = contador horizontal
# $11 = contador de linhas
# $12 = cor branca
# $13 = constante 1
desenharPlayer:
    addi $9, $9, 0

    addi $4, $0, 0x000000

    addi $12, $0, 0xFFFFFF

    # Quantidade de linhas
    addi $11, $0, 2
    
    addi $4, $0, 0x010101
    sw $4, 0($8)
    sw $4, 4($8)
    sw $4, 8($8)
    addi $4, $0, 0x000000
    sw $4, 12($8)
    sw $4, 16($8)
    sw $4, 20($8)
    sw $4, 24($8)
    addi $4, $0, 0x020202
    sw $4, 28($8)
    sw $4, 32($8)
    sw $4, 36($8)
    addi $4, $0, 0x000000
    addi $8, $8, 40

    # Constante para comparação
    addi $13, $0, 1
    
    
    j pulaLinha


bordaHorizontalPlayer:
    beq $9, $0, pulaLinha

    sw $4, 0($8)

    addi $9, $9, -1
    addi $8, $8, 4

    j bordaHorizontalPlayer


pintaPreto:
    addi $11, $11, -1
    addi $4, $0, 0x000000

    sw $4, 0($8)

    lw $4, 98256($8)
    sw $4, -48($8)

    lw $4, 98252($8)
    sw $4, -52($8)

    lw $4, 98308($8)
    sw $4, 4($8)

    lw $4, 98312($8)
    sw $4, 8($8)
    

    addi $4, $0, 0x000000


pulaLinha:
    bne $4, $0, pintaPreto

    ble $11, $0, pintaUltimaLinha

    beq $11, $13, pintaLinhaCinza

    lw $4, 98260($8)
    sw $4, -44($8)

    lw $4, 98256($8)
    sw $4, -48($8)

    lw $4, 98304($8)
    sw $4, 0($8)

    lw $4, 98308($8)
    sw $4, 4($8)
    
    

    addi $4, $0, 0x000000

    addi $8, $8, 468
    sw $4, 0($8)

    addi $9, $0, 10
    addi $8, $8, 4

    addi $4, $0, 0xFFFFFF

    j bordaHorizontalPlayer


pintaUltimaLinha:
    addi $4, $0, 0x000000

    addi $8, $8, 472
    sw $4, 0($8)

    addi $9, $0, 9


pintaUltimaLinhaFor:
    beq $9, $0, endDesenharPlayer

    addi $8, $8, 4
    sw $4, 0($8)

    addi $9, $9, -1

    j pintaUltimaLinhaFor


pintaLinhaCinza:
    addi $9, $0, 10

    addi $8, $8, 468
    sw $4, 0($8)

    addi $8, $8, 4

    # Cinza
    addi $4, $0, 0xDDDDDD

    addi $11, $11, -1

    j bordaHorizontalPlayer


endDesenharPlayer:
    lw $4, 98264($8)
    sw $4, -40($8)

    lw $4, 98260($8)
    sw $4, -44($8)

    lw $4, 98308($8)
    sw $4, 4($8)

    lw $4, 98312($8)
    sw $4, 8($8)

    addi $4, $0, 0x000000

    addi $8, $8, -1572

    j bolaPodeEsquerdaDireita


# $15 = limite temporário
# $16 = posição atual da bola
# $19 = posição inicial da bola
# $20 = direção: +4 direita, -4 esquerda
bolaPodeEsquerdaDireita:
    # Verifica limite esquerdo
    addi $15, $16, 504
    lw $15, 0($15)
    li $4, 0xFFFFFF
    beq $15, $4, bolaVaiDireita

    # Verifica bloco à esquerda
    addi $4, $16, 504
    jal verificarColisaoBloco
    bne $2, $0, bolaVaiDireita

    # Verifica limite direito
    addi $15, $16, 520
    lw $15, 0($15)
    li $4, 0xFFFFFF
    beq $15, $4, bolaVaiEsquerda

    # Verifica bloco à direita
    addi $4, $16, 520
    jal verificarColisaoBloco
    bne $2, $0, bolaVaiEsquerda

    j bolaPodeCimaBaixo

bolaVaiDireita:
    addi $20, $0, 4
    j bolaPodeCimaBaixo


bolaVaiEsquerda:
    addi $20, $0, -4
    j bolaPodeCimaBaixo


bolaPodeCimaBaixo:

    addi $15, $19, 4352
    bge $16, $15, endGame

    # Verifica bloco acima
    addi $4, $16, -512
    jal verificarColisaoBloco
    bne $2, $0, bolaVaiBaixo

    # Verifica bloco abaixo
    addi $4, $16, 1536
    jal verificarColisaoBloco
    bne $2, $0, bolaVaiCima

    # Verifica limites inferiores
    addi $15, $16, 1536
    lw $15, 0($15)

    li $4, 0x000000
    beq $4, $15, bolaVaiCima

    li $4, 0x010101
    beq $4, $15, bolaVaiCima

    li $4, 0x020202
    beq $4, $15, bolaVaiCima

    addi $15, $19, -20992
    ble $16, $15, bolaVaiBaixo

    jal nulltime
    jal nulltime
    jal nulltime
    jal nulltime
    jal nulltime
    jal nulltime
    jal nulltime
    jal nulltime
    jal nulltime
    jal nulltime
    jal nulltime
    jal nulltime
    jal nulltime
    j desenharBola
	
bolaVaiBaixo:
	addi $21, $0, 512
	j desenharBola
bolaVaiCima:
	addi $21, $0, -512
	addi $4, $0, 0x010101
	beq $4, $15, bolaVaiEsquerdaCima
	addi $4, $0, 0x020202
	beq $4, $15, bolaVaiDireitaCima
	j desenharBola
bolaVaiEsquerdaCima:
	addi $15, $0, -4
	beq $20, $15, desenharBola
	addi $20, $0, -4
	j desenharBola
bolaVaiDireitaCima:
	addi $15, $0, 4
	beq $20, $15, desenharBola
	addi $20, $0, 4 
	j desenharBola
# $4  = cor temporária do cenário
# $12 = cor branca da bola
# $16 = posição atual da bola
# $20 = direção da bola
desenharBola:
    
    # Atualiza a posição
    add $16, $16, $20
    add $16, $16, $21
	
    # Desenha a bola
    sw $12, 0($16)
    sw $12, 512($16)
    sw $12, 508($16)
    sw $12, 516($16)
    sw $12, 1024($16)

    # Restaura o cenário ao redor da bola
    lw $4, 97792($16)
    sw $4, -512($16)

    lw $4, 97788($16)
    sw $4, -516($16)

    lw $4, 97796($16)
    sw $4, -508($16)

    lw $4, 98308($16)
    sw $4, 4($16)

    lw $4, 98312($16)
    sw $4, 8($16)

    lw $4, 98300($16)
    sw $4, -4($16)

    lw $4, 98296($16)
    sw $4, -8($16)

    lw $4, 98824($16)
    sw $4, 520($16)

    lw $4, 98808($16)
    sw $4, 504($16)

    lw $4, 99332($16)
    sw $4, 1028($16)

    lw $4, 99336($16)
    sw $4, 1032($16)

    lw $4, 99324($16)
    sw $4, 1020($16)

    lw $4, 99320($16)
    sw $4, 1016($16)

    lw $4, 99840($16)
    sw $4, 1536($16)

    lw $4, 99844($16)
    sw $4, 1540($16)

    lw $4, 99836($16)
    sw $4, 1532($16)
    jal desenharQuadrados

    j controlarPlayer


desenharPerdeu:
    lui $10, 0x1001
    la $8, Perdeu
    addi $9, $0, 8192
forPerdeu:
    beq $9, $0, fimForPerdeu
    lw $4, 0($8)
    sw $4, 0($10)
    addi $8, $8, 4
    addi $10, $10, 4
    addi $9, $9, -1
    j forPerdeu
fimForPerdeu:
    jr $31
endGame:
    jal desenharPerdeu
    j esperarOpcao
startGame:
   blt $22, $0, desenharPlayer
   addi $22, $22, -1
   
   # Velocidade horizontal da bola
    addi $20, $0, 4

    # Direção vertical da bola
    addi $21, $0, -512
    
    j desenharPlayer

# $25 = contador do atraso
# $31 = endereço de retorno

nulltime:
    addi $25, $0, 4000

ntfor:
    beq $25, $0, ntfim
    nop

    addi $25, $25, -1

    j ntfor

ntfim:
    jr $31
desenharQuadrados:
    lui $23, 0x1001
    la $24, blocosAtivos
    la $7, blocosEndereco

desenharQuadradoAzul:
    addi $9, $0, 13
    addi $23, $23, 5708

forQuadradoAzul:
    lbu $26, 0($24)
    beq $26, $zero, pularAzul

    addi $4, $0, 0x215CC4
    sw $4, 0($23)
    sw $4, 4($23)
    sw $4, 8($23)
    sw $4, 512($23)

    addi $4, $0, 0xFFFFFF
    sw $4, 516($23)

    addi $4, $0, 0x286AE0
    sw $4, 12($23)
    sw $4, 16($23)
    sw $4, 520($23)
    sw $4, 524($23)
    sw $4, 1024($23)
    sw $4, 1028($23)
    sw $4, 1032($23)

    addi $4, $0, 0x367FFF
    sw $4, 20($23)
    sw $4, 1536($23)
    sw $4, 1540($23)
    sw $4, 1544($23)
    sw $4, 1036($23)
    sw $4, 1040($23)
    sw $4, 528($23)
    sw $4, 532($23)

    addi $4, $0, 0x4789FE
    sw $4, 1044($23)
    sw $4, 1556($23)
    sw $4, 1552($23)
    sw $4, 1548($23)

pularAzul:
    sw $23, 0($7)
    addi $7, $7, 4
    addi $24, $24, 1
    addi $23, $23, 28
    addi $9, $9, -1
    bgt $9, $0, forQuadradoAzul

    j desenharQuadradoVerde


desenharQuadradoVerde:
    addi $23, $23, 2208
    addi $9, $0, 6
    addi $15, $0, 2

forQuadradoVerde:
    beq $15, $0, desenharQuadradoAmarelo

    lbu $26, 0($24)
    beq $26, $zero, pularVerde

    addi $4, $0, 0x38C424
    sw $4, 0($23)
    sw $4, 4($23)
    sw $4, 8($23)
    sw $4, 512($23)

    addi $4, $0, 0xFFFFFF
    sw $4, 516($23)

    addi $4, $0, 0x41E02B
    sw $4, 12($23)
    sw $4, 16($23)
    sw $4, 520($23)
    sw $4, 524($23)
    sw $4, 1024($23)
    sw $4, 1028($23)
    sw $4, 1032($23)

    addi $4, $0, 0x49FF2F
    sw $4, 20($23)
    sw $4, 1536($23)
    sw $4, 1540($23)
    sw $4, 1544($23)
    sw $4, 1036($23)
    sw $4, 1040($23)
    sw $4, 528($23)
    sw $4, 532($23)

    addi $4, $0, 0x77FC64
    sw $4, 1044($23)
    sw $4, 1556($23)
    sw $4, 1552($23)
    sw $4, 1548($23)

pularVerde:
    sw $23, 0($7)
    addi $7, $7, 4
    addi $24, $24, 1
    addi $23, $23, 28
    addi $9, $9, -1
    bgt $9, $0, forQuadradoVerde

    addi $23, $23, 4
    addi $15, $15, -1
    addi $9, $0, 6
    j forQuadradoVerde


desenharQuadradoAmarelo:
    addi $23, $23, 2204
    addi $9, $0, 13

forQuadradoAmarelo:
    lbu $26, 0($24)
